from __future__ import annotations

from pathlib import Path
import logging

from .models import ProcessResult, stable_url_hash
from .rule_cleaner import clean_transcript_rules

logger = logging.getLogger("BenchmarkIngestion.Pipeline")


class BenchmarkIngestionPipeline:
    def __init__(
        self,
        downloader,
        asr_engine,
        llm_client,
        state_store,
        script_library,
        video_library_dir: str | Path,
        adaptation_reviewer=None,
        max_failures: int = 3,
    ):
        self.downloader = downloader
        self.asr_engine = asr_engine
        self.llm_client = llm_client
        self.adaptation_reviewer = adaptation_reviewer
        self.state_store = state_store
        self.script_library = script_library
        self.video_library_dir = Path(video_library_dir)
        self.video_library_dir.mkdir(parents=True, exist_ok=True)
        self.max_failures = max(1, int(max_failures or 1))

    def process_url(self, url: str) -> ProcessResult:
        if self.state_store.is_processed(url):
            return ProcessResult(url=url, status="skipped", message="已处理，跳过")

        try:
            record = self.state_store.get_url(url)
            existing_video = Path(record.get("video_path", "")) if record.get("video_path") else None
            if existing_video and existing_video.exists() and record.get("status") in {"downloaded", "asr_done", "failed"}:
                video_path = existing_video
            else:
                self.state_store.update_url(url, status="downloading", error="")
                video_path = Path(self.downloader.download(url, self.video_library_dir))
                self.state_store.update_url(url, status="downloaded", video_path=str(video_path), error="")

            asr_result = self.asr_engine.transcribe(video_path)
            raw_script = (asr_result.get("raw_text") or "").strip()
            if not raw_script:
                raise RuntimeError("ASR 未返回文案")
            self.state_store.update_url(url, status="asr_done")

            rule_cleaned = clean_transcript_rules(raw_script) or raw_script
            review = self._review_adaptation(rule_cleaned)
            if review and review.decision == "reject":
                self.state_store.update_url(
                    url,
                    status="adaptation_rejected",
                    video_path=str(video_path),
                    adaptation_reason=review.reason,
                    adaptation_risk_tags=review.risk_tags,
                    error="",
                )
                return ProcessResult(url=url, status="rejected", message=review.reason, video_path=str(video_path))

            adaptation_meta = {}
            if review:
                adaptation_meta = {
                    "adaptation_decision": review.decision,
                    "adaptation_reason": review.reason,
                    "adaptation_risk_tags": review.risk_tags,
                    "adaptation_model": getattr(self.adaptation_reviewer, "model", ""),
                }
            if review and review.decision == "rewrite" and review.adapted_script.strip():
                final_script = review.adapted_script.strip()
            else:
                final_script = self._llm_cleanup(rule_cleaned)

            record = self.script_library.add_script(
                source_url=url,
                raw_script=raw_script,
                cleaned_script=final_script,
                video_path=str(video_path),
                meta={
                    "url_hash": stable_url_hash(url),
                    "asr_language": asr_result.get("language", ""),
                    "asr_duration": asr_result.get("duration"),
                    **adaptation_meta,
                },
            )
            self.state_store.update_url(url, status="llm_done", script_id=record["id"], error="")
            return ProcessResult(url=url, status="completed", video_path=str(video_path), script_id=record["id"])
        except Exception as exc:
            logger.exception("Benchmark ingestion failed: %s", url)
            failure_count = int(self.state_store.get_url(url).get("failure_count", 0) or 0) + 1
            status = "permanent_failed" if failure_count >= self.max_failures else "failed"
            self.state_store.update_url(
                url,
                status=status,
                error=str(exc),
                failure_count=failure_count,
            )
            return ProcessResult(url=url, status="failed", message=str(exc))

    def process_urls(self, urls: list[str], progress=None) -> list[ProcessResult]:
        results = []
        for index, url in enumerate(urls, start=1):
            if progress:
                progress(index, len(urls), url)
            results.append(self.process_url(url))
        return results

    def _llm_cleanup(self, text: str) -> str:
        if not self.llm_client:
            return text
        optimized = self.llm_client.optimize_text(text)
        return (optimized or text).strip()

    def _review_adaptation(self, text: str):
        if not self.adaptation_reviewer:
            return None
        return self.adaptation_reviewer.review_text(text)

from __future__ import annotations

from pathlib import Path
import json

from .models import ensure_parent, now_iso, stable_url_hash


class IngestionStateStore:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._data = self._load()

    def is_processed(self, url: str) -> bool:
        record = self.get_url(url)
        return record.get("status") in {"llm_done", "completed", "adaptation_rejected", "permanent_failed"}

    def get_url(self, url: str) -> dict:
        return self._data["urls"].get(stable_url_hash(url), {})

    def update_url(self, url: str, **fields) -> dict:
        key = stable_url_hash(url)
        record = self._data["urls"].get(key, {"url": url, "created_at": now_iso()})
        record.update(fields)
        record["updated_at"] = now_iso()
        self._data["urls"][key] = record
        self.save()
        return record

    def list_records(self) -> list[dict]:
        return list(self._data["urls"].values())

    def save(self) -> None:
        ensure_parent(self.path)
        self.path.write_text(json.dumps(self._data, ensure_ascii=False, indent=2), encoding="utf-8")

    def _load(self) -> dict:
        if not self.path.exists():
            return {"schema_version": 1, "urls": {}}
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
        except Exception:
            return {"schema_version": 1, "urls": {}}
        if not isinstance(data, dict):
            return {"schema_version": 1, "urls": {}}
        data.setdefault("schema_version", 1)
        data.setdefault("urls", {})
        return data

from __future__ import annotations

from pathlib import Path
import json

from .models import ScriptRecord, ensure_parent, now_iso, safe_filename


class ScriptLibrary:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self.text_dir = self.path.parent / "txt"
        self._data = self._load()

    def add_script(
        self,
        source_url: str,
        raw_script: str,
        cleaned_script: str,
        video_path: str = "",
        title: str = "",
        meta: dict | None = None,
    ) -> dict:
        full_record = ScriptRecord(
            source_url=source_url,
            raw_script=raw_script.strip(),
            cleaned_script=cleaned_script.strip(),
            video_path=video_path,
            title=title,
            meta=meta or {},
        ).to_dict()
        script_path = self._write_script_text(full_record)
        record = self._to_index_record(full_record, script_path)
        self._data["scripts"].append(record)
        self.save()
        return self._hydrate_record(record)

    def list_scripts(self, status: str | None = None) -> list[dict]:
        scripts = list(self._data["scripts"])
        if status:
            scripts = [item for item in scripts if item.get("status") == status]
        return [self._hydrate_record(item) for item in scripts]

    def mark_used(self, script_id: str) -> bool:
        for record in self._data["scripts"]:
            if record.get("id") == script_id:
                record["status"] = "used"
                record["used_at"] = now_iso()
                self.save()
                return True
        return False

    def save(self) -> None:
        ensure_parent(self.path)
        self.path.write_text(json.dumps(self._data, ensure_ascii=False, indent=2), encoding="utf-8")

    def _load(self) -> dict:
        if not self.path.exists():
            return {"schema_version": 1, "scripts": []}
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
        except Exception:
            return {"schema_version": 1, "scripts": []}
        if not isinstance(data, dict):
            return {"schema_version": 1, "scripts": []}
        data.setdefault("schema_version", 1)
        data.setdefault("scripts", [])
        return data

    def _write_script_text(self, record: dict) -> str:
        self.text_dir.mkdir(parents=True, exist_ok=True)
        name_seed = record.get("title") or record.get("cleaned_script", "")[:24]
        filename = f"{record['id']}_{safe_filename(name_seed, 'script')}.txt"
        path = self.text_dir / filename
        path.write_text(record.get("cleaned_script", "").strip(), encoding="utf-8")
        return str(path)

    def _to_index_record(self, record: dict, script_path: str) -> dict:
        return {
            "id": record.get("id", ""),
            "source_url": record.get("source_url", ""),
            "script_path": script_path,
            "preview": record.get("cleaned_script", "").replace("\n", " ")[:80],
            "video_path": record.get("video_path", ""),
            "title": record.get("title", ""),
            "status": record.get("status", "ready"),
            "created_at": record.get("created_at", ""),
            "used_at": record.get("used_at", ""),
            "meta": record.get("meta", {}),
        }

    def _hydrate_record(self, record: dict) -> dict:
        hydrated = dict(record)
        if "cleaned_script" not in hydrated:
            hydrated["cleaned_script"] = self._read_script_text(record.get("script_path", ""))
        hydrated.setdefault("raw_script", "")
        return hydrated

    def _read_script_text(self, script_path: str) -> str:
        if not script_path:
            return ""
        path = Path(script_path)
        try:
            if path.exists():
                return path.read_text(encoding="utf-8").strip()
        except Exception:
            return ""
        return ""

from __future__ import annotations


ASR_CORRECTIONS = [
    ("看挂", "看卦"),
    ("看卦子", "看卦"),
    ("借色", "戒色"),
    ("甚虚", "肾虚"),
    ("甚好的人", "肾好的人"),
    ("甚好", "肾好"),
    ("精满不思音", "精满不思淫"),
    ("气满不思时", "气满不思食"),
    ("精化器", "精化气"),
    ("面红耳深", "面红耳赤"),
    ("死语", "私欲"),
    ("地狱下", "地狱相"),
    ("奶头乐", "奶嘴乐"),
    ("音符经", "阴符经"),
    ("重彩票", "中彩票"),
    ("道德底下", "道德底线"),
    ("的食候", "的时候"),
    ("这个食候", "这个时候"),
    ("那个食候", "那个时候"),
    ("有食候", "有时候"),
    ("食间", "时间"),
    ("食代", "时代"),
]

FULL_LINE_FILLERS = {"嗯", "啊", "对吧", "是吧", "你知道吗", "明白吗"}
LINE_START_FILLERS = ("然后呢", "然后", "咱先说", "咱可以先", "我告诉你", "就是说", "嗯", "啊")
SALES_KEYWORDS = ("下单", "购买", "链接", "小黄车", "橱窗", "商品", "价格", "优惠", "限时", "秒杀", "点击")


def clean_transcript_rules(text: str) -> str:
    lines = [line.strip() for line in (text or "").splitlines() if line.strip()]
    if not lines and text.strip():
        lines = [text.strip()]
    if _is_sales_content(lines):
        return ""
    lines = _correct(lines)
    processed = []
    for line in lines:
        line = _remove_filler(line)
        if line:
            processed.append(_add_punctuation(line))
    return "\n\n".join(_create_paragraphs(processed)).strip()


def _correct(lines: list[str]) -> list[str]:
    text = "\n".join(lines)
    for wrong, right in ASR_CORRECTIONS:
        text = text.replace(wrong, right)
    return text.splitlines()


def _remove_filler(line: str) -> str:
    line = line.strip()
    if line in FULL_LINE_FILLERS:
        return ""
    for filler in LINE_START_FILLERS:
        if line.startswith(filler):
            line = line[len(filler):].strip()
            if line.startswith(("，", "。", "！", "？")):
                line = line[1:].strip()
            break
    return line


def _add_punctuation(line: str) -> str:
    if not line or line[-1] in "。！？：；":
        return line
    if line.endswith(("吗", "呢", "啥")):
        return line + "？"
    return line + "。"


def _create_paragraphs(lines: list[str]) -> list[str]:
    paragraphs: list[str] = []
    current: list[str] = []
    break_words = ("第一", "第二", "第三", "首先", "其次", "最后", "那么", "所以", "但是", "因为", "因此", "其实", "为什么", "怎么")
    for line in lines:
        should_break = current and (line.startswith(break_words) or len(current) >= 5)
        if should_break:
            paragraphs.append("".join(current))
            current = [line]
        else:
            current.append(line)
    if current:
        paragraphs.append("".join(current))
    return paragraphs


def _is_sales_content(lines: list[str]) -> bool:
    count = 0
    for line in lines:
        count += sum(1 for keyword in SALES_KEYWORDS if keyword in line)
    return count >= 3

from __future__ import annotations

from pathlib import Path
import logging

from .models import safe_filename, stable_url_hash

logger = logging.getLogger("BenchmarkIngestion.Downloader")


class DownloadError(RuntimeError):
    pass


def explain_yt_dlp_error(error: Exception | str) -> str:
    text = str(error)
    if "Failed to decrypt with DPAPI" in text:
        return (
            "无法解密浏览器 Cookie（Windows DPAPI 权限限制）。"
            "请改用浏览器扩展导出 douyin.com 的 Netscape 格式 cookies.txt，"
            "然后在“抖音 Cookie”的 Cookie 文件里选择该文件。"
        )
    if "Fresh cookies" in text:
        return (
            "抖音要求新鲜 Cookie。请先在浏览器里打开抖音并确认能播放该视频，"
            "或导出 douyin.com 的 cookies.txt 后在页面中选择。"
        )
    if "Could not copy Chrome cookie database" in text or "Permission denied" in text:
        return (
            "无法复制浏览器 Cookie 数据库。请完全关闭对应浏览器后台进程，"
            "或改用 cookies.txt 文件。"
        )
    return text


class YtDlpVideoDownloader:
    def __init__(
        self,
        cookie_file: str = "",
        cookie_string: str = "",
        cookies_from_browser: str = "",
        crtubeget_dir: str = "",
        douyin_fallback_downloader=None,
    ):
        self.cookie_file = cookie_file
        self.cookie_string = cookie_string
        self.cookies_from_browser = cookies_from_browser
        self.crtubeget_dir = crtubeget_dir
        self.douyin_fallback_downloader = douyin_fallback_downloader

    def download(self, url: str, output_dir: str | Path) -> Path:
        output_root = Path(output_dir)
        output_root.mkdir(parents=True, exist_ok=True)
        fallback_name = stable_url_hash(url)
        outtmpl = str(output_root / "%(title).120B-%(id)s.%(ext)s")

        if self._should_use_douyin_cr_first(url):
            return self._douyin_fallback().download(url, output_root)

        try:
            return self._download_with_yt_dlp(url, output_root, outtmpl)
        except DownloadError as exc:
            if self._can_fallback_to_douyin_cr(url, str(exc)):
                return self._douyin_fallback().download(url, output_root)
            raise

    def _download_with_yt_dlp(self, url: str, output_root: Path, outtmpl: str | Path) -> Path:
        try:
            import yt_dlp
        except ImportError as exc:
            raise DownloadError("yt-dlp 未安装，请先安装依赖或在 requirements.txt 中启用 yt-dlp") from exc

        fallback_name = stable_url_hash(url)
        opts = self._build_opts(outtmpl)

        try:
            with yt_dlp.YoutubeDL(opts) as ydl:
                info = ydl.extract_info(url, download=True)
        except Exception as exc:
            raise DownloadError(explain_yt_dlp_error(exc)) from exc

        requested = info.get("requested_downloads") or []
        for item in requested:
            filepath = item.get("filepath")
            if filepath and Path(filepath).exists():
                return Path(filepath)

        title = safe_filename(info.get("title") or fallback_name, fallback_name)
        video_id = safe_filename(str(info.get("id") or fallback_name), fallback_name)
        candidates = list(output_root.glob(f"{title}-{video_id}.*")) or list(output_root.glob(f"*{video_id}*"))
        for candidate in candidates:
            if candidate.is_file():
                return candidate

        raise DownloadError(f"下载完成后未找到输出文件: {url}")

    def _can_fallback_to_douyin_cr(self, url: str, error_message: str) -> bool:
        if "抖音要求新鲜 Cookie" not in error_message and "Fresh cookies" not in error_message:
            return False
        return self._is_douyin_with_fallback(url)

    def _should_use_douyin_cr_first(self, url: str) -> bool:
        return self._is_douyin_with_fallback(url)

    def _is_douyin_with_fallback(self, url: str) -> bool:
        try:
            from .douyin_cr import is_douyin_url
        except Exception:
            return False
        return is_douyin_url(url) and bool(self.douyin_fallback_downloader or self.crtubeget_dir)

    def _douyin_fallback(self):
        if self.douyin_fallback_downloader:
            return self.douyin_fallback_downloader
        from .douyin_cr import DouyinCRVideoDownloader

        self.douyin_fallback_downloader = DouyinCRVideoDownloader(
            self.crtubeget_dir,
            cookie_file=self.cookie_file,
        )
        return self.douyin_fallback_downloader

    def _build_opts(self, outtmpl: str | Path) -> dict:
        opts = {
            "format": "bv*+ba/best",
            "outtmpl": str(outtmpl),
            "merge_output_format": "mp4",
            "quiet": True,
            "no_warnings": True,
            "retries": 3,
            "fragment_retries": 3,
            "socket_timeout": 30,
            "nocheckcertificate": True,
        }
        if self.cookie_file:
            opts["cookiefile"] = self.cookie_file
        if self.cookies_from_browser:
            opts["cookiesfrombrowser"] = (self.cookies_from_browser,)
        return opts

from __future__ import annotations

import http.cookiejar
import json
import logging
import subprocess
import tempfile
import time
from pathlib import Path
from urllib.parse import urlparse

import requests

from .downloader import DownloadError
from .models import safe_filename, stable_url_hash

logger = logging.getLogger("BenchmarkIngestion.DouyinCR")

DEFAULT_UA = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
    "(KHTML, like Gecko) Chrome/132.0.0.0 Safari/537.36"
)
AB_JS_URL = "http://www.cr-soft.top/js/ab.js"


def normalize_crck_cookie_output(text: str) -> str:
    lines = []
    for line in text.splitlines():
        if line.startswith("Cookie:"):
            line = line[len("Cookie:"):].lstrip()
        lines.append(line)
    normalized = "\n".join(lines).strip() + "\n"
    if not normalized.startswith("# Netscape HTTP Cookie File"):
        raise DownloadError("CR TubeGet cookie 导出不是 Netscape 格式")
    return normalized


def parse_aweme_detail(data: dict, referer: str) -> dict:
    item = data.get("aweme_detail")
    if not item and data.get("item_list"):
        item = data["item_list"][0]
    if not item:
        raise DownloadError("抖音详情接口未返回视频信息")

    video = item.get("video") or {}
    play_addr = video.get("play_addr") or video.get("playAddr") or {}
    url_list = play_addr.get("url_list") or play_addr.get("urlList") or []
    if not url_list:
        raise DownloadError("抖音详情接口未返回可下载视频直链")

    cover = video.get("cover") or {}
    cover_urls = cover.get("url_list") or cover.get("urlList") or []
    download_urls = _build_download_candidates(video)
    if not download_urls:
        download_urls = [str(url_list[0]).replace("playwm", "play")]
    direct_url = download_urls[0]
    return {
        "id": str(item.get("aweme_id") or item.get("id") or stable_url_hash(referer)),
        "title": item.get("desc") or item.get("caption") or "douyin_video",
        "direct_url": direct_url,
        "download_urls": download_urls,
        "thumbnail": cover_urls[0] if cover_urls else "",
        "duration": (item.get("duration") or 0) / 1000,
        "referer": referer,
    }


def _build_download_candidates(video: dict) -> list[str]:
    candidates: list[str] = []

    play_addr = video.get("play_addr") or video.get("playAddr") or {}
    uri = play_addr.get("uri") or video.get("uri")
    height = int(video.get("height") or play_addr.get("height") or 0)
    if uri:
        ratio = "1080p" if height > 720 else "720p"
        candidates.append(f"https://aweme.snssdk.com/aweme/v1/play/?video_id={uri}&ratio={ratio}&line=0")

    for url in play_addr.get("url_list") or play_addr.get("urlList") or []:
        candidates.append(str(url).replace("playwm", "play"))

    for bitrate in video.get("bit_rate") or video.get("bitRate") or []:
        br_play_addr = bitrate.get("play_addr") or bitrate.get("playAddr") or {}
        for url in br_play_addr.get("url_list") or br_play_addr.get("urlList") or []:
            candidates.append(str(url).replace("playwm", "play"))

    seen = set()
    unique = []
    for url in candidates:
        if not url or url in seen:
            continue
        seen.add(url)
        unique.append(url)
    return unique


def is_douyin_url(url: str) -> bool:
    host = urlparse(url).netloc.lower()
    return "douyin.com" in host or "iesdouyin.com" in host


class DouyinCRResolver:
    def __init__(
        self,
        crtubeget_dir: str | Path,
        cookie_file: str = "",
        timeout: int = 30,
    ):
        self.crtubeget_dir = Path(crtubeget_dir)
        self.cookie_file = cookie_file
        self.timeout = timeout
        self.qjs_path = self.crtubeget_dir / "qjs.exe"
        self.crck_path = self.crtubeget_dir / "crck.exe"

    def resolve(self, url: str) -> dict:
        if not is_douyin_url(url):
            raise DownloadError("CR TubeGet fallback 仅支持抖音链接")
        if not self.qjs_path.exists():
            raise DownloadError(f"未找到 CR TubeGet qjs.exe: {self.qjs_path}")

        with tempfile.TemporaryDirectory(prefix="douyin_cr_") as tmp:
            tmp_path = Path(tmp)
            session = requests.Session()
            session.headers.update({"User-Agent": DEFAULT_UA})
            self._load_cookies(session, url, tmp_path)

            redirect = session.get(url, allow_redirects=True, timeout=self.timeout)
            redirect.raise_for_status()
            referer = redirect.url
            item_id = self._extract_item_id(referer)
            if not item_id:
                raise DownloadError(f"未能从抖音链接解析作品 ID: {referer}")

            detail = self._fetch_aweme_detail(session, item_id, referer, tmp_path)
            return parse_aweme_detail(detail, referer)

    def _load_cookies(self, session: requests.Session, url: str, tmp_path: Path) -> None:
        cookie_paths = []
        if self.crck_path.exists():
            exported = subprocess.check_output(
                [str(self.crck_path), url],
                cwd=str(self.crtubeget_dir),
                timeout=self.timeout,
                text=True,
                stderr=subprocess.STDOUT,
            )
            cr_cookie = tmp_path / "crtubeget_cookies.txt"
            cr_cookie.write_text(normalize_crck_cookie_output(exported), encoding="utf-8")
            cookie_paths.append(cr_cookie)
        if self.cookie_file:
            cookie_paths.append(Path(self.cookie_file))

        for cookie_path in cookie_paths:
            if not cookie_path.exists():
                continue
            jar = http.cookiejar.MozillaCookieJar(str(cookie_path))
            jar.load(ignore_discard=True, ignore_expires=True)
            session.cookies.update(jar)

    def _fetch_aweme_detail(
        self,
        session: requests.Session,
        item_id: str,
        referer: str,
        tmp_path: Path,
    ) -> dict:
        args = (
            "app_name=aweme&aid=1128&device_platform=iphone&os_version=12.3.1"
            f"&device_id={int(time.time() * 1000)}&aweme_id={item_id}"
        )
        api_url = (
            "https://www.douyin.com/aweme/v1/web/aweme/detail/?"
            f"{args}&a_bogus={self._a_bogus(args, tmp_path)}"
        )
        headers = {
            "User-Agent": DEFAULT_UA,
            "Referer": referer,
            "Accept": "application/json, text/plain, */*",
        }
        response = session.get(api_url, headers=headers, timeout=self.timeout)
        response.raise_for_status()
        try:
            return response.json()
        except json.JSONDecodeError as exc:
            raise DownloadError("抖音详情接口返回了非 JSON 内容") from exc

    def _a_bogus(self, args: str, tmp_path: Path) -> str:
        ab_js = tmp_path / "ab.js"
        ab_source = self._load_ab_js()
        ab_js.write_text(ab_source, encoding="utf-8")
        runner = tmp_path / "run_ab.js"
        runner.write_text(
            "var window={}; var navigator={userAgent:%r};\n%s\nconsole.log(window.ab(%r,%r));\n"
            % (DEFAULT_UA, ab_source, args, DEFAULT_UA),
            encoding="utf-8",
        )
        return subprocess.check_output(
            [str(self.qjs_path), str(runner)],
            cwd=str(self.crtubeget_dir),
            timeout=self.timeout,
            text=True,
        ).strip()

    def _load_ab_js(self) -> str:
        cache_path = self.crtubeget_dir / "ab.js"
        try:
            response = requests.get(AB_JS_URL, timeout=self.timeout)
            response.raise_for_status()
            source = response.text.strip()
            if "window.ab" not in source:
                raise DownloadError("远程 ab.js 内容不完整")
            try:
                cache_path.write_text(source, encoding="utf-8")
            except OSError as exc:
                logger.warning("写入 ab.js 缓存失败: %s", exc)
            return source
        except Exception as exc:
            if cache_path.exists():
                logger.warning("远程 ab.js 不可用，改用本地缓存: %s", exc)
                cached = cache_path.read_text(encoding="utf-8").strip()
                if cached:
                    return cached
            raise DownloadError(f"获取抖音 a_bogus 脚本失败，且没有可用缓存: {exc}") from exc

    @staticmethod
    def _extract_item_id(url: str) -> str:
        parsed = urlparse(url)
        parts = [part for part in parsed.path.split("/") if part]
        for marker in ("video", "note"):
            if marker in parts:
                index = parts.index(marker)
                if index + 1 < len(parts):
                    return parts[index + 1]
        return ""


class DouyinCRVideoDownloader:
    def __init__(self, crtubeget_dir: str | Path, cookie_file: str = "", timeout: int = 30):
        self.resolver = DouyinCRResolver(crtubeget_dir, cookie_file=cookie_file, timeout=timeout)
        self.timeout = timeout

    def download(self, url: str, output_dir: str | Path) -> Path:
        resolved = self.resolver.resolve(url)
        output_root = Path(output_dir)
        output_root.mkdir(parents=True, exist_ok=True)
        title = safe_filename(resolved.get("title") or "douyin_video", "douyin_video")
        video_id = safe_filename(resolved.get("id") or stable_url_hash(url), stable_url_hash(url))
        target = output_root / f"{title}-{video_id}.mp4"
        tmp_target = target.with_suffix(target.suffix + ".part")

        headers_list = self._download_headers(resolved.get("referer") or url)
        errors = []
        for candidate in resolved.get("download_urls") or [resolved["direct_url"]]:
            for headers in headers_list:
                try:
                    self._download_candidate(candidate, tmp_target, headers)
                    break
                except requests.HTTPError as exc:
                    status = exc.response.status_code if exc.response is not None else "unknown"
                    errors.append(f"{status} {candidate}")
                    if tmp_target.exists():
                        tmp_target.unlink()
                    continue
                except requests.RequestException as exc:
                    errors.append(f"{type(exc).__name__} {candidate}")
                    if tmp_target.exists():
                        tmp_target.unlink()
                    continue
            if tmp_target.exists() and tmp_target.stat().st_size > 0:
                break
        else:
            raise DownloadError("CR TubeGet fallback 下载失败: " + "; ".join(errors[-3:]))

        tmp_target.replace(target)
        if target.stat().st_size <= 0:
            raise DownloadError("CR TubeGet fallback 下载到空文件")
        return target

    def _download_candidate(self, candidate: str, tmp_target: Path, headers: dict) -> None:
        with requests.get(
            candidate,
            headers=headers,
            stream=True,
            timeout=self.timeout,
            allow_redirects=True,
        ) as response:
            response.raise_for_status()
            with tmp_target.open("wb") as fh:
                for chunk in response.iter_content(chunk_size=1024 * 1024):
                    if chunk:
                        fh.write(chunk)

    def _download_headers(self, referer: str) -> list[dict]:
        ios_ua = (
            "Mozilla/5.0 (iPhone; CPU iPhone OS 18_2 like Mac OS X) "
            "AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.2 Mobile/15E148 Safari/604.1"
        )
        return [
            {"User-Agent": ios_ua, "Referer": referer},
            {"User-Agent": DEFAULT_UA, "Referer": referer},
            {"User-Agent": ios_ua},
            {"User-Agent": DEFAULT_UA},
        ]

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
import json
import logging
import re

import requests

logger = logging.getLogger("BenchmarkIngestion.AdaptationReviewer")


REVIEW_SYSTEM_PROMPT = """你是一位短视频对标文案的适配审查员。你的任务是保守过滤不适合进入后续批量生产链路的文案。

账号固定人设：
- 男性
- 男道士
- 男命理师
- 面向命理、玄学、修行相关短视频口播

审查原则：保守过滤，宁可拒绝，也不要让时效错位、身份错位、作者私货或女性视角进入后续流程。

重点识别风险：
1. 时效错位：清明节、春节、中元节、冬至、去年、2025 年、月份、生肖年等与当前日期不匹配的表达
2. 身份错位：女性视角、女性博主口吻、宝妈、姐妹们、老公、男朋友等不适合男道士/男命理师人设的表达
3. 作者自述：原作者本人经历、账号经历、门店、收徒、地域、客户案例等强绑定内容
4. 过往经历：讲述个人过去经历、人生故事、成长经历、从业经历、亲身遭遇、曾经如何如何等内容，默认 reject
5. 不可迁移内容：核心观点依赖原作者身份、经历或已过期事件，改写后容易显得虚假

决策规则：
- keep：没有明显风险，可以原样进入文案库
- rewrite：只有轻微可迁移问题，删除或替换少量人称/称呼后仍然忠实可用
- reject：存在明显时效错位、身份错位、作者自述、过往经历、女性视角、不可迁移经历，或你不确定是否安全

只输出 JSON，不要输出解释文本。格式如下：
{
  "decision": "keep | rewrite | reject",
  "reason": "一句话说明原因",
  "risk_tags": ["时效错位", "身份错位", "作者自述", "过往经历", "女性视角", "不可迁移经历"],
  "adapted_script": "keep 时可为空或原文；rewrite 时输出改写后的可用文案；reject 时必须为空"
}
"""


@dataclass
class AdaptationReviewResult:
    decision: str
    reason: str = ""
    risk_tags: list[str] = field(default_factory=list)
    adapted_script: str = ""


class ScriptAdaptationReviewer:
    def __init__(
        self,
        api_key: str,
        model: str = "doubao-seed-2.0-pro",
        base_url: str = "https://ark.cn-beijing.volces.com/api/coding/v3",
        timeout: int = 90,
    ):
        self.api_key = api_key
        self.model = model
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def review_text(self, text: str) -> AdaptationReviewResult:
        source = (text or "").strip()
        if not source:
            return reject_result("空文案，拒绝入库", ["empty_script"])

        today = datetime.now().strftime("%Y-%m-%d")
        messages = [
            {"role": "system", "content": REVIEW_SYSTEM_PROMPT},
            {
                "role": "user",
                "content": f"当前日期：{today}\n\n【待审查文案】\n{source}",
            },
        ]
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}",
        }

        try:
            initial_max_tokens = max(2000, min(8000, len(source) * 4))
            token_budgets = [initial_max_tokens]
            if initial_max_tokens < 8000:
                token_budgets.append(8000)

            last_result = None
            for attempt, max_tokens in enumerate(token_budgets, start=1):
                payload = {
                    "model": self.model,
                    "messages": messages,
                    "temperature": 0.1,
                    "max_tokens": max_tokens,
                }
                response = requests.post(
                    f"{self.base_url}/chat/completions",
                    headers=headers,
                    json=payload,
                    timeout=self.timeout,
                )
                if response.status_code != 200:
                    logger.error("适配审查 LLM 调用失败: HTTP %s, %s", response.status_code, response.text)
                    return reject_result("适配审查 LLM 调用失败，保守拒绝", ["review_failed"])

                choice = response.json().get("choices", [{}])[0]
                message = choice.get("message", {})
                content = message.get("content", "")
                finish_reason = str(choice.get("finish_reason", "")).lower()
                result = parse_review_result(content)
                last_result = result
                if result.risk_tags != ["review_failed"]:
                    return result

                can_retry = attempt < len(token_budgets) and (
                    finish_reason == "length" or not content.strip()
                )
                if not can_retry:
                    logger.warning(
                        "适配审查结果解析失败: finish_reason=%s, content_preview=%r",
                        finish_reason,
                        content[:500],
                    )
                    return result

                logger.warning(
                    "适配审查输出疑似被截断，准备使用更大 max_tokens 重试: finish_reason=%s, max_tokens=%s",
                    finish_reason,
                    max_tokens,
                )

            return last_result or reject_result("适配审查结果解析失败，保守拒绝", ["review_failed"])
        except Exception as exc:
            logger.error("适配审查 LLM 调用异常: %s", exc, exc_info=True)
            return reject_result("适配审查 LLM 调用异常，保守拒绝", ["review_failed"])


def parse_review_result(text: str) -> AdaptationReviewResult:
    try:
        payload = json.loads(strip_json_wrappers(text))
    except Exception:
        return reject_result("适配审查结果解析失败，保守拒绝", ["review_failed"])

    if not isinstance(payload, dict):
        return reject_result("适配审查结果不是 JSON 对象，保守拒绝", ["review_failed"])

    decision = str(payload.get("decision", "")).strip().lower()
    reason = str(payload.get("reason", "")).strip()
    risk_tags = payload.get("risk_tags", [])
    if not isinstance(risk_tags, list):
        risk_tags = [str(risk_tags).strip()] if risk_tags else []
    risk_tags = [str(tag).strip() for tag in risk_tags if str(tag).strip()]
    adapted_script = str(payload.get("adapted_script", "")).strip()

    if decision not in {"keep", "rewrite", "reject"}:
        return reject_result("适配审查 decision 无效，保守拒绝", ["review_failed"])
    if decision == "rewrite" and not adapted_script:
        return reject_result("适配审查要求改写但未返回文案，保守拒绝", ["review_failed"])
    if decision == "reject":
        adapted_script = ""

    return AdaptationReviewResult(
        decision=decision,
        reason=reason or "适配审查完成",
        risk_tags=risk_tags,
        adapted_script=adapted_script,
    )


def strip_json_wrappers(text: str) -> str:
    cleaned = (text or "").strip()
    cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\s*```$", "", cleaned)
    return cleaned.strip()


def reject_result(reason: str, risk_tags: list[str] | None = None) -> AdaptationReviewResult:
    return AdaptationReviewResult(
        decision="reject",
        reason=reason,
        risk_tags=risk_tags or [],
        adapted_script="",
    )

